+        final int docId = docIdSupplier.getAsInt();
+        int matchedTerms = 0;
+
+        try {
+            for (PostingsEnum postingsEnum : postingsSupplier.get()) {
+                if (postingsEnum != null && postingsEnum.advance(docId) == docId && postingsEnum.freq() > 0) {
