+
+    @Override
+    public int hashCode() {
+        return Objects.hash(
+            totalCount,
+            successCount,
+            failureReasons,
+            took,
+            tookMrtTrue,
+            tookMrtFalse,
+            remotesPerSearchMax,
+            remotesPerSearchAvg,
+            skippedRemotes,
+            featureCounts,
+            clientCounts,
+            byRemoteCluster
+        );
+    }
+
+    @Override
+    public String toString() {
+        return Strings.toString(this, true, true);
+    }
+}
